def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression string containing non-negative integers,
    + - * /, parentheses, unary minus and spaces. True division is used for /.
    """
    expr = expr.replace(" ", "")
    if not expr:
        raise ValueError("Empty expression")

    # Stack to hold numbers and operators
    # We'll process numbers and operators sequentially.
    # To handle unary minus and parentheses, we'll use a stack for numbers
    # and a separate stack for operators, but a simpler approach for this specific
    # constraint (no eval) is to use the two-stack algorithm (shunting-yard)
    # or a recursive descent parser. Given the constraints, a recursive descent
    # is cleanest.

    # Tokenizer helper
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit() or s[i] == '.':
                j = i
                if s[i] == '.':
                    j += 1
                    while j < n and s[j].isdigit():
                        j += 1
                else:
                    while j < n and (s[j].isdigit() or s[j] == '.'):
                        j += 1
                tokens.append(float(s[i:j]))
                i = j
            elif s[i] in '+-*/()':
                tokens.append(s[i])
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        return tokens

    tokens = tokenize(expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        val = tokens[pos[0]]
        pos[0] += 1
        return val

    def parse_primary():
        token = peek()
        if token is None:
            raise ValueError("Unexpected end of expression")

        if token == '(':
            consume() # consume '('
            val = parse_expression()
            token = peek()
            if token != ')':
                raise ValueError("Missing closing parenthesis")
            consume() # consume ')'
            return val

        if token == ')':
            raise ValueError("Unexpected closing parenthesis")

        if token == '-':
            consume() # consume '-'
            val = parse_primary()
            return -val

        if token == '+':
            consume() # consume '+'
            val = parse_primary()
            return val

        num = consume()
        return num

    def parse_term():
        left = parse_primary()
        while peek() in ('*', '/'):
            op = consume()
            if op == '*':
                right = parse_term()
                left = left * right
            elif op == '/':
                right = parse_term()
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right
        return left

    def parse_expression():
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            if op == '+':
                right = parse_term()
                left = left + right
            elif op == '-':
                right = parse_term()
                left = left - right
        return left

    # Start parsing
    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected tokens remaining")

    return result
