def lis(xs):
    if not xs:
        return 0

    tails = []
    for x in xs:
        # Binary search for the first element in tails >= x
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid

        # If x is larger than all elements in tails, append it
        if left == len(tails):
            tails.append(x)
        else:
            # Replace the found element with x to maintain the smallest tail for a subsequence of length left+1
            tails[left] = x

    return len(tails)
