import heapq

def shortest_path(n, edges, src, dst):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * n
    parent = [-1] * n
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        if u == dst:
            break

        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                parent[v] = u
                heapq.heappush(pq, (dist[v], v))

    # Reconstruct path
    if dist[dst] == float('inf'):
        return (None, [])

    path = []
    curr = dst
    while curr != -1:
        path.append(curr)
        curr = parent[curr]
    path.reverse()

    return (dist[dst], path)
