def evaluate(expr):
    # Remove spaces
    expr = expr.replace(" ", "")

    # Handle unary minus at the start or after operator
    def fix_unary(s):
        result = []
        i = 0
        while i < len(s):
            if s[i] == '-' and (i == 0 or s[i-1] in '+-*/()'):
                result.append('(-')
                i += 1
            else:
                result.append(s[i])
                i += 1
        return ''.join(result)

    expr = fix_unary(expr)

    # Tokenize: split by operators and numbers
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            tokens.append(('num', num))
        elif expr[i] in '+-*/':
            tokens.append(('op', expr[i]))
            i += 1
        elif expr[i] == '(':
            tokens.append(('lp', expr[i]))
            i += 1
        elif expr[i] == ')':
            tokens.append(('rp', expr[i]))
            i += 1
        else:
            i += 1

    # Recursive descent parser
    pos = [0]  # Use list to allow modification in nested function

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        token = tokens[pos[0]]
        pos[0] += 1
        return token

    def parse_primary():
        token = peek()
        if token is None:
            return 0
        if token[0] == 'num':
            return token[1]
        elif token[0] == 'lp':
            val = parse_expression()
            consume()  # consume '('
            val = parse_primary()
            consume()  # consume ')'
            return val
        else:
            raise ValueError(f"Unexpected token: {token}")

    def parse_additive():
        left = parse_multiplicative()
        while peek() and peek()[0] == '+':
            consume()
            right = parse_multiplicative()
            left += right
        return left

    def parse_multiplicative():
        left = parse_unary()
        while peek() and peek()[0] in '*/':
            op = consume()[0]
            right = parse_unary()
            if op == '*':
                left *= right
            else:
                left /= right
        return left

    def parse_unary():
        if peek() and peek()[0] == '-':
            consume()
            return -parse_unary()
        return parse_primary()

    try:
        result = parse_additive()
        if pos[0] < len(tokens):
            raise ValueError("Unexpected token at end of expression")
        return result
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")
