def shortest_path(n, edges, src, dst):
    import heapq

    # Initialize distances and previous node tracker
    dist = {i: float('inf') for i in range(n)}
    prev = {i: None for i in range(n)}
    dist[src] = 0

    # Priority queue: (distance, node)
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)

        # If we reached the destination, we can stop early
        if u == dst:
            break

        # If current distance is greater than already found shortest distance, skip
        if d > dist[u]:
            continue

        # Explore neighbors
        for v, w in edges:
            if v < n:  # Ensure v is within valid node range
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(pq, (dist[v], v))

    # Check if destination is unreachable
    if dist[dst] == float('inf'):
        return (None, [])

    # Reconstruct path
    path = []
    curr = dst
    while curr is not None:
        path.append(curr)
        curr = prev[curr]

    path.reverse()
    return (dist[dst], path)
