def evaluate(expr):
    # Remove spaces
    expr = expr.replace(" ", "")

    # Stack to hold numbers and operators
    stack = []
    # Current number being built
    current_num = 0
    # Sign for the current number (+1 for positive, -1 for negative)
    sign = 1

    # We'll iterate through the string character by character
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        if char.isdigit():
            # Build the number
            current_num = current_num * 10 + int(char)
            i += 1
        elif char == '+':
            # Apply the previous number with its sign
            if current_num > 0:
                stack.append(sign * current_num)
                current_num = 0
            sign = 1
            i += 1
        elif char == '-':
            # Handle unary minus or subtraction
            if current_num > 0:
                stack.append(sign * current_num)
                current_num = 0
            # Check if it's a unary minus at the start or after an operator/parenthesis
            if i == 0 or expr[i-1] in '(*-':
                sign = -1
            else:
                sign = -1
            i += 1
        elif char == '*':
            # Apply the previous number with its sign
            if current_num > 0:
                stack.append(sign * current_num)
                current_num = 0
            sign = 1
            i += 1
        elif char == '/':
            # Apply the previous number with its sign
            if current_num > 0:
                stack.append(sign * current_num)
                current_num = 0
            sign = 1
            i += 1
        elif char == '(':
            # Push a marker for parentheses
            stack.append('(')
            i += 1
        elif char == ')':
            # Process until we hit the matching '('
            while stack and stack[-1] != '(':
                if stack[-1] == '+':
                    stack.pop()
                elif stack[-1] == '-':
                    stack.pop()
                elif stack[-1] == '*':
                    stack.pop()
                elif stack[-1] == '/':
                    stack.pop()
                else:
                    # Pop the number
                    val = stack.pop()
                    stack.append(sign * val)
            if stack:
                stack.pop()  # Remove the '('
            i += 1
        else:
            i += 1

    # Apply the last number
    if current_num > 0:
        stack.append(sign * current_num)

    # Perform operations with correct precedence
    # We need to handle * and / first, then + and -
    # Since we pushed numbers and operators in order, we can process * and / first

    # First pass: handle * and /
    while len(stack) >= 2:
        op = stack.pop()
        if op in ['*', '/']:
            val = stack.pop()
            if op == '*':
                stack.append(val * val)
            else:
                stack.append(val // val)  # Integer division for true division of integers
        else:
            stack.append(op)

    # Second pass: handle + and -
    while len(stack) >= 2:
        op = stack.pop()
        if op in ['+', '-']:
            val = stack.pop()
            if op == '+':
                stack.append(val + val)
            else:
                stack.append(val - val)
        else:
            stack.append(op)

    return stack[0] if stack else 0
